import type { Patch, PluginSpec } from "../spec.ts"

const typesWhy = "Import the identical helper/constant directly; @typescript-eslint/utils root also eagerly loads ESLint classes (not used by these rules)"

// `import { names } from '@typescript-eslint/utils'` → the same names from @typescript-eslint/types.
function fromTypes(names: string): Patch {
    return [`import { ${names} } from '@typescript-eslint/utils'`, `import { ${names} } from '@typescript-eslint/types'`, typesWhy]
}

